"""Render CSV evidence without silently replacing missing/censored values with zero."""
import csv
import json
import math
from pathlib import Path

ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'docs/simulation'
RESULT=OUT/'results'

def read(name):
    p=RESULT/name
    return list(csv.DictReader(p.open(encoding='utf-8-sig'))) if p.exists() else []

def fmt(v):
    if isinstance(v,bool): return '예' if v else '아니요'
    if v is None or v=='': return '—'
    try:
        x=float(v)
        return f'{x:,.1f}' if math.isfinite(x) else '—'
    except (ValueError,TypeError): return str(v).replace('|','/').replace('\n',' ')

def table(rows, columns):
    return '\n'.join(['| '+' | '.join(label for key,label in columns)+' |',
                      '| '+' | '.join('---' for _ in columns)+' |']+
                     ['| '+' | '.join(fmt(r.get(key)) for key,label in columns)+' |' for r in rows])+'\n'

